package com.vms.vendorcontractmanagement.repository; import com.vms.vendorcontractmanagement.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import org.springframework.data.domain.*; import java.time.*; public interface ContractRepository extends JpaRepository<Contract,Long>{boolean existsByContractNumber(String contractNumber); boolean existsByVendorIdAndStatus(Long id,String status); @Query("select c from Contract c where (:search is null or lower(c.contractNumber) like lower(concat('%',:search,'%')) or lower(c.vendor.vendorName) like lower(concat('%',:search,'%'))) and (:status is null or c.status=:status)") Page<Contract> search(String search,String status,Pageable pageable); @Query("select c from Contract c where c.endDate between :today and :until") java.util.List<Contract> expiring(@Param("today") LocalDate today,@Param("until") LocalDate until); }
